import { cp, lstat, mkdir, readdir, rename, rm } from 'node:fs/promises';
import { join } from 'node:path';

import type { FileMigration } from '../migrations.types';

/** Frozen with the migration, so a later rename of the store's own names cannot change what this step does. */
export const LEGACY_LIBRARY_DIR = 'workflows';
const LIBRARY_DIR = 'teams';
const LEGACY_TEAM_SUFFIX = '.geniro.yaml';
const TEAM_SUFFIX = '.team.yaml';
export const MIGRATED_DIR = '.migrated';
const PARTIAL_SUFFIX = '.partial';

/** Regenerated by the store under its new name on the next builder chat. */
const LEGACY_SCHEMA_FILE = '.workflow.schema.json';

async function exists(path: string): Promise<boolean> {
  try {
    await lstat(path);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      return false;
    }
    throw error;
  }
}

function renamedEntry(name: string): string | null {
  if (name === LEGACY_SCHEMA_FILE) {
    return null;
  }
  return name.endsWith(LEGACY_TEAM_SUFFIX)
    ? `${name.slice(0, -LEGACY_TEAM_SUFFIX.length)}${TEAM_SUFFIX}`
    : name;
}

/**
 * Moves the library from `<userData>/workflows/` to `<userData>/teams/`, each
 * `<slug>.geniro.yaml` becoming `<slug>.team.yaml`; backups, the user's own
 * files and folders keep their names. Every original is moved into
 * `workflows/.migrated/` only after its copy landed whole: a copy is written
 * under a `.partial` name and renamed into place, so an entry already present
 * is complete and is not copied again, and a run cut short resumes where it
 * stopped. `down` puts the originals back and sets `teams/` aside rather than
 * deleting it, since it may hold edits made after the move.
 */
export const teamLibraryFiles: FileMigration = {
  id: '0003-team-library-files',
  kind: 'files',
  async up({ userDataDir }) {
    const from = join(userDataDir, LEGACY_LIBRARY_DIR);
    if (!(await exists(from))) {
      return;
    }
    const to = join(userDataDir, LIBRARY_DIR);
    const migrated = join(from, MIGRATED_DIR);
    const entries = (await readdir(from)).filter(
      (name) => name !== MIGRATED_DIR,
    );
    if (entries.length === 0) {
      return;
    }
    await mkdir(to, { recursive: true });
    await mkdir(migrated, { recursive: true });
    for (const name of entries) {
      const target = renamedEntry(name);
      if (target !== null && !(await exists(join(to, target)))) {
        const partial = join(to, `${target}${PARTIAL_SUFFIX}`);
        await rm(partial, { recursive: true, force: true });
        await cp(join(from, name), partial, {
          recursive: true,
          errorOnExist: true,
          force: false,
          preserveTimestamps: true,
        });
        await rename(partial, join(to, target));
      }
      await rename(join(from, name), join(migrated, name));
    }
  },
  async down({ userDataDir }) {
    const from = join(userDataDir, LEGACY_LIBRARY_DIR);
    const migrated = join(from, MIGRATED_DIR);
    if (!(await exists(migrated))) {
      return;
    }
    for (const name of await readdir(migrated)) {
      await rename(join(migrated, name), join(from, name));
    }
    await rm(migrated, { recursive: true, force: true });
    const teams = join(userDataDir, LIBRARY_DIR);
    if (await exists(teams)) {
      await rename(teams, `${teams}.rolled-back-${Date.now()}`);
    }
  },
};
